import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"36、【明夷】 离下坤上","description":"周易口诀义 - 36、【明夷】 离下坤上","frontmatter":{"title":"36、【明夷】 离下坤上","description":"周易口诀义 - 36、【明夷】 离下坤上"},"headers":[],"relativePath":"zh/classics/koujueyi/038.md","filePath":"zh/classics/koujueyi/038.md"}'),r={name:"zh/classics/koujueyi/038.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_36、【明夷】-离下坤上" tabindex="-1">36、【明夷】 离下坤上 <a class="header-anchor" href="#_36、【明夷】-离下坤上" aria-label="Permalink to “36、【明夷】 离下坤上”">​</a></h1><p>彖曰：明入地中，「明夷」。内文明而外柔顺，以蒙大难，文王以之。「利艰贞」，晦其明也。内难而能正其志，箕子以之。象曰：明入地中，「明夷」。君子以莅众，用晦而明。</p><p>初九：明夷于飞，垂其翼。君子于行，三日不食。有攸往，主人有言。</p><p>象曰：「君子于行」，义不食也。</p><p>六二：明夷，夷于左股，用拯马壮，吉。</p><p>象曰：六二之吉，顺以则也。</p><p>九三，明夷于南狩，得其大首，不可疾贞。</p><p>象曰：南狩之志，乃大得也。</p><p>六四，入于左腹，获明夷之心，于出门庭。</p><p>象曰：「入于左腹」，获心意也。</p><p>六五，箕子之明夷，利贞。</p><p>象曰：箕子之贞，明不可息也。</p><p>上六，不明晦，初登于天，后入于地。</p><p>象曰：「初登于天」，照四国也；「后入于地」，失则也。</p><p>解读</p><p>「明夷，利艰贞」者，夷，伤也，离为日，喻日入地中，伤明之象，故曰「明夷」。以人事明之，亦犹君在上，臣不敢显其明德，必须艰固为贞，又不可随世倾邪，故曰「利艰贞」也。象曰「明入地中，明夷」者，夫日之为道，即合升高照耀，今在地中，伤其光耀之象。「君子以莅众，用晦而明」者，莅，临也，晦，暗也。故君子当是时以临于众，内怀明德，外彰晦暗，无为无事，清净不欺，闭智塞耀，故老子云「我无为而人自化」是也。</p><p>「初九，明夷于飞，垂其翼，君子于行，三日不食。有攸往，主人有言」者，上六以阴居上，是暗君之象。初九既居无位之地，未食暗君之禄，可以逃避危难，不由轨路，如鸟之飞，故曰「于飞」；怀惧而行，以求隐翳，故曰「垂其翼」；虽处危惧，志存道义，故曰「于行」；切于逃难，饥不暇食，故曰「三日不食」；处危惧之时，与众乖异，故主人有相疑之言，故曰「有攸往，主人有言」也。</p><p>「六二，明夷，夷于左股，用拯马壮吉」者，左者，明所伤小也。左股被伤，犹得顺而处位。六二以柔居中，不为刚猛之事，即不为暗主所疑，犹处其位，然后时进退，乃得随时，用拯马而避之，得吉也。</p><p>「九三，明夷于南狩，得其大首，不可疾贞」者，南是阳明之方也；狩者，征伐之义。九三以离明之极，而以征伐至暗之主，乃获暗君之头首，故曰「南狩，得其大首」也。既诛暗主，将正其民，民迷日久，即可化之以渐，不可速使从正，故曰「不可疾贞」也。</p><p>「六四：入子左腹，获明夷之心，于出门庭」者，左者，取其顺也；腹者，获其心。既知君意，虽近不危，纵使逃难，不远适，止于门庭而已也。</p><p>「六五箕子之明夷，利贞」者，最近暗君，犹箕子之近殷纣，执正不回而不能灭，利以正贞，故小象云「明不可息」也。息，灭也。</p><p>上六：不明晦，初登于天，后入于地者，处明夷之极，是暗晦之主，殷纣当之也。「初登于位」，本谓光德显于四方，及其无道，果致被伐，至于丧灭，故曰「后入于地」也。</p>',22)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
